        Assertions.assertEquals('H', ebr.read());
        Assertions.assertEquals('e', ebr.read());
        Assertions.assertEquals('l', ebr.read());
        Assertions.assertEquals('l', ebr.read());
        Assertions.assertEquals('o', ebr.read());
